x:2;max-width:440px;margin-top:-3%}.eyebrow{font-size:9px;letter-spacing:2px;font-weight:800;color:#718a74}.eyebrow span{color:#d39b66;font-size:13px;margin-right:4px}h1,h2,h3,p{margin-top:0}.screen h1,.modal-card h2{font-family:'Playfair Display',serif;color:#34483f;letter-spacing:-1.6px}.screen h1{font-size:clamp(34px,4.2vw,56px);line-height:1.04;margin:17px 0 12px}.screen h1 em,.modal-card h2 em{color:#8b9b70;font-weight:600}.screen-copy p{font-size:13px;line-height:1.65;color:#697a6d;max-width:300px;margin-bottom:20px}.primary-button{background:#527c69;color:#fffdf7;border:0;border-radius:9px;padding:13px 18px;font:700 12px 'DM Sans';letter-spacing:.2px;box-shadow:0 7px 16px #41665427;cursor:pointer;transition:transform .18s,background .18s}.primary-button:hover{background:#3e6b59;transform:translateY(-2px)}.primary-button span{font-size:16px;margin-left:19px}.tiny-note{font-size:10px;color:#8b9281;margin-top:12px}.hero-cat{position:absolute;right:13%;bottom:16%;width:205px;height:174px}.cat-hero{position:absolute;width:135px;height:105px;border-radius:55% 52% 46% 45%;background:#df925d;bottom:2px;left:40px;box-shadow:inset -12px -8px #c9794d}.cat-hero:before{content:'';position:absolute;left:19px;top:-35px;width:103px;height:76px;border-radius:50%;background:#e5a56b;box-shadow:inset -8px -2px #d98e5b}.ear{position:absolute;z-index:2;top:-41px;width:34px;height:43px;background:#d88b59;clip-path:polygon(50% 0,100% 100%,0 100%)}.ear:after{content:'';position:absolute;inset:12px 9px 5px;background:#e8b1a0;clip-path:polygon(50% 0,100% 100%,0 100%)}.ear.left{left:28px;transform:rotate(-13deg)}.ear.right{right:22px;transform:rotate(12deg)}.eye{position:absolute;top:15px;width:6px;height:9px;border-radius:50%;background:#33453d;z-index:4}.eye.one{left:42px}.eye.two{right:37px}.nose{position:absolute;z-index:5;top:31px;left:64px;width:9px;height:6px;background:#9e6558;clip-path:polygon(50% 100%,0 0,100% 0)}.whisker{position:absolute;height:1px;width:32px;background:#855