ogress-track{flex:1;background:#eeeae0;border-radius:8px;height:5px;overflow:hidden}.progress-track span{display:block;width:0;height:100%;background:#92ae83;border-radius:8px;transition:width .25s}.quest-progress b{font-size:9px;color:#789078;min-width:28px;text-align:right}.text-button{border:0;background:none;color:#66836c;font:700 10px 'DM Sans';cursor:pointer}.text-button span{font-size:14px;margin-left:5px}.cat-roster{display:flex;gap:9px;margin-top:12px}.roster-cat{position:relative;border:1px solid #eee8dd;border-radius:9px;background:#f9f6ef;width:49px;height:49px;display:grid;place-items:center;font-size:24px;cursor:pointer;transition:transform .15s,background .15s}.roster-cat:hover{transform:translateY(-2px)}.roster-cat.active{border-color:#9bb39a;background:#edf3e7;box-shadow:0 0 0 2px #d7e5d2}.roster-cat.locked{filter:grayscale(.8);opacity:.58}.roster-cat .lock{position:absolute;right:3px;bottom:2px;font-size:9px}.roster-cat .level-badge{position:absolute;top:-5px;right:-4px;background:#e3aa72;border-radius:10px;padding:2px 4px;color:white;font:700 7px 'DM Sans'}.tip-card{display:flex;gap:10px;align-items:center;padding:11px 13px;background:#f0f3e8;border-color:#e6eadc;box-shadow:none}.tip-card>span{display:grid;place-items:center;flex:none;width:25px;height:25px;border-radius:8px;background:#e1e9d8;color:#8a9e71}.tip-card p{font-size:9px;color:#798572;line-height:1.5;margin:0}.tip-card b{color:#66775f;font-size:10px}aside footer{text-align:center;font-size:7px;color:#aaa99b;letter-spacing:1.35px;padding-top:1px}aside footer span{color:#db998c;font-size:10px}.mobile-controls{display:none}.pause-overlay{position:absolute;inset:0;z-index:5;background:#34443e70;display:grid;place-items:center;transition:opacity .2s}.pause-overlay.hidden{display:none}.pause-card{background:#fffdf7;border-radius:17px;padding:26px 30px;text-align:center;box-shadow:0 15px 35px #24372f45}.pause-icon{display:grid;place-items:center;margin:auto auto 9px;width:37px;height:37px;background:#eaf0e4;color:#60806a;border-radius:12px}.pause-card h2{font:600 22px 'Playfair Display';margin:0 0 7px}.pause-card p{font-size:11px;color:#879188;margin-bottom:17px}.modal{position:fixed;inset:0;z-index:20;background:#30423a80;backdrop-filter:blur(4px);display:grid;place-items:center;padding:18px;opacity:1;transition:opacity .2s}.modal.hidden{display:none}.modal-card{position:relative;background:#fffdf7;border:1px solid #eee8dc;border-radius:20px;padding:29px 32px;width:min(100%,480px);box-shadow:0 25px 80px #26393040;animation:pop .25s ease}@keyframes pop{from{transform:translateY(12px);opacity:0}to{transform:none;opacity:1}}.modal-close{position:absolute;right:16px;top:14px;border:0;background:#f2efe7;width:28px;height:28px;border-radius:50%;font-size:20px;color:#728076;cursor:pointer}.modal-card h2{font-size:32px;line-height:1.08;margin:12px 0 8px}.modal-intro,.modal-card>p{font-size:12px;line-height:1.6;color:#849087;margin-bottom:17px}.shop-list{display:flex;flex-direction:column;gap:9px;max-height:47vh;overflow:auto;padding-right:2px}.shop-item{display:flex;align-items:center;gap:11px;border:1px solid #eee9df;background:#faf8f2;border-radius:11px;padding:10px}.shop-emoji{display:grid;place-items:center;width:42px;height:42px;border-radius:11px;background:#f2e8d9;font-size:25px;flex:none}.shop-item-info{flex:1}.shop-item-info b{display:block;font-size:12px;color:#46584e}.shop-item-info small{display:block;font-size:9px;color:#89938a;margin-top:3px}.shop-buy{border:0;background:#668672;color:white;padding:8px 10px;border-radius:7px;font:700 10px 'DM Sans';white-space:nowrap;cursor:pointer}.shop-buy:disabled{background:#e4e6dc;color:#9aa194;cursor:default}.shop-wallet{margin-top:14px;text-align:center;font-size:10px;color:#869087}.shop-wallet b{color:#647e65}.level-modal{text-align:center;width:min(100%,405px);padding:33px 37px}.level-modal .eyebrow{justify-content:center}.confetti{font-size:17px;color:#e2b279;letter-spacing:7px;margin-bottom:12px}.level-modal h2{font-size:35px}.level-modal>p{margin:10px 0 17px}.level-reward{display:flex;align-items:center;justify-content:center;gap:10px;background:#f5f2e8;border-radius:10px;padding:11px;margin:0 auto 17px;width:170px;text-align:left}.level-reward>span{font-size:24px}.level-reward b{color:#638367;font-size:16px}.level-modal .primary-button{width:100%}.secondary-button{margin-top:9px;border:0;background:none;color:#778b75;font:700 10px 'DM Sans';cursor:pointer}.gameover-modal{text-align:center;width:min(100%,390px)}.gameover-modal h2{font-size:34px}.gameover-modal .primary-button{margin-top:5px}.toast{position:fixed;z-index:30;left:50%;bottom:23px;transform:translate(-50%,20px);background:#344a41;color:#fffdf7;border-radius:24px;padding:10px 17px;font-size:11px;font-weight:700;opacity:0;pointer-events:none;transition:all .22s;box-shadow:0 8px 25px #263c3240}.toast.show{opacity:1;transform:translate(-50%,0)}
