nt-size:13px}.stats-row{grid-column:span 2}.stat-card{min-height:55px}.quest-card{grid-column:span 2;padding:11px 13px}.collection-card{grid-column:span 2;padding:11px 13px}.tip-card{grid-column:span 2}.roster-cat{width:47px;height:44px}.side-panel aside footer{grid-column:span 2}.modal-card{padding:25px 21px}.modal-card h2{font-size:28px}.level-modal{padding:28px 23px}.pause-card{padding:21px 20px}.pause-card .primary-button{padding:11px 12px;font-size:10px}}
