(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  const W = 960, H = 540, groundY = 478;
  const $ = (id) => document.getElementById(id);
  const cats = [
    { id:'marmalade', name:'Marmalade', emoji:'🐈', color:'#df925d', ability:'A nimble little jumper', skill:'Double jump', price:0, level:1, detail:'A second little hop in midair.' },
    { id:'pudding', name:'Pudding', emoji:'🐈‍⬛', color:'#687179', ability:'A dash of mischief', skill:'Paw dash', price:18, level:2, detail:'Dash through trouble with a burst of speed.' },
    { id:'nimbus', name:'Nimbus', emoji:'🐈', color:'#aab9bd', ability:'Yarn is drawn to you', skill:'Yarn magnet', price:32, level:3, detail:'Nearby yarn balls come rolling your way.' },
    { id:'clover', name:'Clover', emoji:'🐈', color:'#d5b66e', ability:'A very lucky kitty', skill:'Lucky leap', price:45, level:4, detail:'A powerful leap and a little extra air.' }
  ];
  const fresh = { yarn:0, level:1, lives:7, selected:'marmalade', owned:{marmalade:1}, upgrades:{marmalade:1} };
  let save = loadSave();
  let state = 'title', paused = false, world = null, player = null, cameraX = 0, collected = 0, levelStartYarn = 0;
  let keys = Object.create(null), touch = Object.create(null), lastTime = 0, frame = 0, toastTimer = 0, soundOn = true, audioCtx = null;

  function loadSave() { try { const s = JSON.parse(localStorage.getItem('whisker-woods-save') || 'null'); return s ? {...fresh,...s,owned:{...fresh.owned,...s.owned},upgrades:{...fresh.upgrades,...s.upgrades}} : {...fresh,owned:{...fresh.owned},upgrades:{...fresh.upgrades}}; } catch { return {...fresh,owned:{...fresh.owned},upgrades:{...fresh.upgrades}}; } }
  function persist() { try { localStorage.setItem('whisker-woods-save', JSON.stringify(save)); } catch {} }
  function currentCat() { return cats.find(c=>c.id===save.selected) || cats[0]; }
  function rounded(x,y,w,h,r,fill,stroke) { ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke();} }
  function initLevel() {
    const n = save.level;
    const spacing = 12;
    const length = 2440 + Math.min(n,8)*110;
    const platforms = [
      {x:270,y:390,w:150},{x:510,y:335,w:140},{x:735,y:405,w:155},{x:990,y:365,w:150},
      {x:1215,y:310,w:150},{x:1455,y:390,w:160},{x:1710,y:340,w:150},{x:1955,y:395,w:170}
    ];
    const yarns=[];
    // Friendly, fixed placements: three easy floor finds and platform trails.
    for (let x=160;x<length-140;x+=170) yarns.push({x,y:groundY-34-Math.sin(x*.024)*6,got:false});
    platforms.forEach((p,i)=>{yarns.push({x:p.x+p.w*.5,y:p.y-28,got:false}); if(i%2===0)yarns.push({x:p.x+p.w*.77,y:p.y-28,got:false});});
    const hazards=[];
    for(let x=650;x<length-200;x+=510) hazards.push({x,y:groundY-22,base:x,range:90,dir:1});
    world={length,platforms,yarns,hazards,level:n,decor:[]};
    let seed=n*73+19; const rand=()=>{seed=(seed*9301+49297)%233280;return seed/233280;};
    for(let x=0;x<length+400;x+=70+rand()*100) world.decor.push({x,kind:rand(),scale:.55+rand()*.65});
    player={x:65,y:groundY-50,vx:0,vy:0,w:34,h:43,onGround:false,jumps:0,invuln:0,face:1,abilityCooldown:0,dash:0,trail:[]};
    cameraX=0;collected=0;levelStartYarn=save.yarn;
    $('levelName').textContent=`${levelTitle(n)} · ${String(n).padStart(2,'0')}`;
    refreshUI();
  }
  function levelTitle(n){return ['Mossy Meadow','Bluebell Hollow','Pumpkin Patch','Moonlit Grove','Daisy Downs'][((n-1)%5)];}
  function refreshUI(){
    const cat=currentCat();$('catName').textContent=cat.name;$('catAvatar').textContent=cat.emoji;$('catAbility').textContent=cat.ability;
    $('yarnCount').textContent=save.yarn;$('lifeCount').textContent='♥ '.repeat(Math.max(0,save.lives)).trim() || '—';
    $('questProgress').style.width=(world?Math.min(100,collected/world.yarns.length*100):0)+'%';
    $('questText').textContent=world?`${collected} / ${world.yarns.length}`:'0 / 0';
    renderRoster();
    if(!$('shopModal').classList.contains('hidden')) renderShop();
  }
  function renderRoster(){
    $('catRoster').innerHTML=cats.map(c=>{const owned=!!save.owned[c.id],active=save.selected===c.id;return `<button class="roster-cat ${active?'active':''} ${owned?'':'locked'}" data-cat="${c.id}" title="${c.name}${owned?'':` — unlock at level ${c.level}`}" aria-label="${c.name}">${c.emoji}${owned?'':`<span class="lock">🔒</span>`}${owned&&save.upgrades[c.id]>1?`<span class="level-badge">+${save.upgrades[c.id]-1}</span>`:''}</button>`}).join('');
    $('catRoster').querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{const c=cats.find(x=>x.id===b.dataset.cat);if(save.owned[c.id])selectCat(c);else openShop();});
  }
  function renderShop(){
