(() => {
  'use strict';

  const $ = (id) => document.getElementById(id);
  const canvas = $('game');
  const ctx = canvas.getContext('2d');
  const W = canvas.width, H = canvas.height;
  const GROUND_Y = 466;
  const STORAGE_KEY = 'whisker-woods-save-v1';
  const cats = [
    { id: 'marmalade', name: 'Marmalade', emoji: '🐈', color: '#d99a68', ability: 'Nimble little jumper', cost: 0, skill: 'Extra-high jump' },
    { id: 'pudding', name: 'Pudding', emoji: '🐈', color: '#ecd7ba', ability: 'A second chance in the air', cost: 18, skill: 'Double jump' },
    { id: 'nimbus', name: 'Nimbus', emoji: '🐈‍⬛', color: '#8999a8', ability: 'A breezy burst of speed', cost: 28, skill: 'Cloud dash' },
    { id: 'clover', name: 'Clover', emoji: '🐈', color: '#99ae78', ability: 'A lucky little shield', cost: 38, skill: 'Protective purr' }
  ];
  const freshSave = () => ({ yarn: 0, lives: 7, level: 1, unlocked: ['marmalade'], upgrades: { marmalade: 0 }, selected: 'marmalade' });
  function readSave() {
    try {
      const raw = JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null');
      if (!raw || typeof raw !== 'object') return freshSave();
      const next = freshSave();
      next.yarn = Math.max(0, Number(raw.yarn) || 0);
      next.lives = Math.max(1, Math.min(7, Number(raw.lives) || 7));
      next.level = Math.max(1, Math.min(99, Number(raw.level) || 1));
      next.unlocked = Array.isArray(raw.unlocked) ? [...new Set(['marmalade', ...raw.unlocked.filter(id => cats.some(c => c.id === id))])] : next.unlocked;
      next.upgrades = raw.upgrades && typeof raw.upgrades === 'object' ? raw.upgrades : next.upgrades;
      next.selected = next.unlocked.includes(raw.selected) ? raw.selected : 'marmalade';
      return next;
    } catch { return freshSave(); }
  }
  let save = readSave();
  let state = 'title', paused = false, soundOn = true, lastTime = 0, cameraX = 0, toastTimer = 0;
  let world, player, keys = Object.create(null), touch = { left: false, right: false }, particles = [], levelYarnStart = 0;
  const rnd = (a, b) => a + Math.random() * (b - a);
  const clamp = (n, a, b) => Math.max(a, Math.min(b, n));
  const currentCat = () => cats.find(c => c.id === save.selected) || cats[0];
  const persist = () => { try { localStorage.setItem(STORAGE_KEY, JSON.stringify(save)); } catch {} refreshUI(); };
  const levelTitle = (level) => ['Mossy Meadow', 'Dewdrop Woods', 'Sunbeam Hollow', 'Clover Creek', 'Moonberry Trail'][((level - 1) % 5)];
  function rounded(x, y, w, h, r, color) {
    ctx.fillStyle = color; ctx.beginPath(); ctx.roundRect(x, y, w, h, Math.min(r, w / 2, h / 2)); ctx.fill();
  }
  function beep(freq = 550, duration = .08) {
    if (!soundOn) return;
    try { const audio = new (window.AudioContext || window.webkitAudioContext)(); const osc = audio.createOscillator(), gain = audio.createGain();
      osc.type = 'sine'; osc.frequency.value = freq; gain.gain.setValueAtTime(.055, audio.currentTime); gain.gain.exponentialRampToValueAtTime(.001, audio.currentTime + duration);
      osc.connect(gain); gain.connect(audio.destination); osc.start(); osc.stop(audio.currentTime + duration); osc.onended = () => audio.close(); } catch {}
  }
  function notify(message) {
    const el = $('toast'); el.textContent = message; el.classList.add('show'); clearTimeout(toastTimer);
    toastTimer = setTimeout(() => el.classList.remove('show'), 2200);
  }
  function makeWorld() {
    const length = 3650 + Math.min(save.level - 1, 8) * 150;
    const platforms = [{ x: 0, y: GROUND_Y, w: 570, h: 90 }, { x: 650, y: GROUND_Y, w: 560, h: 90 }, { x: 1290, y: GROUND_Y, w: 590, h: 90 }, { x: 1950, y: GROUND_Y, w: 550, h: 90 }, { x: 2570, y: GROUND_Y, w: 570, h: 90 }, { x: 3210, y: GROUND_Y, w: length - 3210, h: 90 }];
    const ledges = [
      [250, 380, 125], [440, 325, 115], [730, 365, 140], [930, 300, 130], [1130, 382, 110],
      [1370, 350, 130], [1580, 292, 120], [1770, 365, 125], [2010, 375, 140], [2230, 310, 120],
      [2440, 365, 110], [2670, 355, 130], [2860, 292, 130], [3060, 370, 115], [3310, 360, 140], [3500, 300, 120]
    ];
    ledges.forEach(([x, y, w]) => platforms.push({ x, y, w, h: 18, ledge: true }));
    const yarn = [];
    const addYarn = (x, y) => yarn.push({ x, y, got: false, phase: rnd(0, Math.PI * 2) });
    [[110,415],[195,415],[280,344],[335,344],[465,289],[520,289],[735,415],[790,329],[850,329],[960,264],[1020,264],[1150,347],[1335,415],[1405,314],[1465,314],[1600,256],[1660,256],[1795,329],[1995,415],[2060,339],[2130,339],[2250,274],[2310,274],[2455,329],[2620,415],[2705,319],[2770,319],[2885,256],[2945,256],[3090,334],[3260,415],[3340,324],[3400,324],[3525,264],[3580,264]].forEach(p => addYarn(p[0], p[1]));
    const hazards = [[570, GROUND_Y - 10], [1210, GROUND_Y - 10], [1880, GROUND_Y - 10], [2505, GROUND_Y - 10], [3145, GROUND_Y - 10]].map(([x, y]) => ({ x, y, w: 28, h: 10 }));
    return { length, platforms, yarn, hazards, exitX: length - 100, clouds: Array.from({ length: 10 }, (_, i) => ({ x: i * 440 + rnd(0, 180), y: rnd(55, 190), scale: rnd(.7, 1.25) })) };
  }
  function initLevel() {
    world = makeWorld(); cameraX = 0; particles = []; levelYarnStart = save.yarn;
    player = { x: 70, y: GROUND_Y - 44, vx: 0, vy: 0, w: 36, h: 44, face: 1, grounded: false, jumps: 0, invuln: 0, dash: 0, shield: 0, abilityCooldown: 0, abilityFlash: 0 };
    refreshUI();
  }
  function refreshUI() {
    if (!world) return;
    $('levelName').textContent = `${levelTitle(save.level)} · ${String(save.level).padStart(2, '0')}`;
    $('yarnCount').textContent = save.yarn;
    $('lifeCount').textContent = '♥ '.repeat(save.lives).trim() || '♡';
    $('catName').textContent = currentCat().name;
    $('catAbility').textContent = currentCat().ability;
    $('catAvatar').textContent = currentCat().emoji;
    $('questProgress').style.width = `${Math.round(world.yarn.filter(y => y.got).length / world.yarn.length * 100)}%`;
    $('questText').textContent = `${world.yarn.filter(y => y.got).length} / ${world.yarn.length}`;
    $('tipText').textContent = `${currentCat().skill} · press Shift or ✦ to use your skill.`;
    $('shopYarn').textContent = save.yarn;
    renderRoster();
  }
  function renderRoster() {
    $('catRoster').innerHTML = cats.map(cat => {
      const unlocked = save.unlocked.includes(cat.id), active = save.selected === cat.id, upgrade = save.upgrades[cat.id] || 0;
      return `<button class="roster-cat${active ? ' active' : ''}${unlocked ? '' : ' locked'}" data-roster="${cat.id}" aria-label="${cat.name}${unlocked ? '' : ', locked'}">${cat.emoji}${!unlocked ? '<span class="lock">🔒</span>' : upgrade ? `<span class="level-badge">${upgrade + 1}</span>` : ''}</button>`;
    }).join('');
  }
  function renderShop() {
    $('shopYarn').textContent = save.yarn;
    $('shopList').innerHTML = cats.map(cat => {
      const owned = save.unlocked.includes(cat.id), price = cat.cost, selected = save.selected === cat.id;
      const upgrade = save.upgrades[cat.id] || 0, upgradePrice = 16 + upgrade * 14;
      let button;
      if (!owned) button = `<button class="shop-buy" data-buy="${cat.id}" ${save.yarn < price ? 'disabled' : ''}>🧶 ${price}</button>`;
      else if (!selected) button = `<button class="shop-buy" data-select="${cat.id}">Choose</button>`;
      else if (upgrade < 3) button = `<button class="shop-buy" data-upgrade="${cat.id}" ${save.yarn < upgradePrice ? 'disabled' : ''}>Upgrade · 🧶 ${upgradePrice}</button>`;
      else button = '<button class="shop-buy" disabled>Max level</button>';
      const sub = !owned ? `${cat.skill} · unlock this friend` : `${cat.skill}${upgrade ? ` · upgrade ${upgrade}/3` : ''}`;
      return `<div class="shop-item"><div class="shop-emoji">${cat.emoji}</div><div class="shop-item-info"><b>${cat.name}</b><small>${sub}</small></div>${button}</div>`;
    }).join('');
  }
  function openShop() {
    const modal = $('shopModal'); renderShop(); modal.classList.remove('hidden');
    if (state === 'playing') { paused = true; $('pauseOverlay').classList.add('hidden'); }
  }
  function closeShop() {
    $('shopModal').classList.add('hidden');
    if (state === 'playing') paused = false;
  }
  function startGame() {
    save.lives = 7; persist(); initLevel(); state = 'playing'; paused = false;
    $('startScreen').classList.add('hidden'); $('gameOverModal').classList.add('hidden'); $('levelModal').classList.add('hidden');
    $('pauseOverlay').classList.add('hidden'); notify(`Off to ${levelTitle(save.level)}!`); beep(620);
  }

function jump() {
  if (state !== 'playing' || paused) return;
  const cat = currentCat(), upgrade = save.upgrades[cat.id] || 0;
  if (player.grounded || (cat.id === 'pudding' && player.jumps < 2)) {
    player.vy = player.grounded ? -(cat.id === 'marmalade' ? 11.6 : 10.3) - upgrade * .45 : -9.1;
    player.grounded = false; player.jumps++; beep(420 + player.jumps * 65, .07);
  }
}
function useAbility() {
  if (state !== 'playing' || paused || player.abilityCooldown > 0) return;
  const cat = currentCat();
  if (cat.id === 'nimbus') { player.dash = 12; player.vx = player.face * (13 + (save.upgrades[cat.id] || 0)); player.vy *= .35; }
  else if (cat.id === 'clover') { player.shield = 360 + (save.upgrades[cat.id] || 0) * 90; }
  else if (cat.id === 'pudding') { if (player.jumps < 2 && !player.grounded) jump(); else { player.invuln = 35; notify('Pudding pounces with a little sparkle!'); } }
  else { if (player.grounded) jump(); else player.vy = Math.min(player.vy, -8.7 - (save.upgrades[cat.id] || 0) * .5); }
  player.abilityCooldown = 120; player.abilityFlash = 16; beep(760, .12);
}
function loseLife() {
  if (player.invuln > 0 || player.shield > 0) { if (player.shield > 0) player.shield = 0; player.invuln = 65; return; }
  save.lives = Math.max(0, save.lives - 1); persist(); beep(180, .2);
  if (!save.lives) { state = 'gameover'; $('gameOverModal').classList.remove('hidden'); return; }
  player.x = Math.max(50, Math.floor(player.x / 650) * 650 + 55); player.y = GROUND_Y - 70; player.vx = 0; player.vy = 0; player.invuln = 100; player.jumps = 0;
  cameraX = clamp(player.x - W * .28, 0, world.length - W); notify(`A little tumble! ${save.lives} paw power left.`);
}
function completeLevel() {
  if (state !== 'playing') return;
  state = 'level'; paused = true; const reward = 8 + Math.max(0, world.yarn.filter(y => y.got).length);
  save.yarn += reward; persist();
  $('levelReward').textContent = `+${reward}`;
  $('levelMessage').textContent = `You gathered ${world.yarn.filter(y => y.got).length} yarn balls and found the cottage. What a lovely adventure!`;
  $('levelModal').classList.remove('hidden'); beep(830, .2);
}
function update(dt) {
  if (state !== 'playing' || paused || !player) return;
  const step = Math.min(2.2, dt / 16.67), p = player;
  if (p.invuln > 0) p.invuln -= step;
  if (p.shield > 0) p.shield -= step;
  if (p.abilityCooldown > 0) p.abilityCooldown -= step;
  if (p.abilityFlash > 0) p.abilityFlash -= step;
  if (p.dash > 0) p.dash -= step;
  const left = keys.ArrowLeft || keys.a || keys.A || touch.left;
  const right = keys.ArrowRight || keys.d || keys.D || touch.right;
  const accel = p.dash > 0 ? 0 : .58 * step;
  if (left) { p.vx -= accel; p.face = -1; }
  if (right) { p.vx += accel; p.face = 1; }
  if (!left && !right && p.dash <= 0) p.vx *= Math.pow(.79, step);
  p.vx = clamp(p.vx, -5.2, 5.2);
  if (p.dash > 0) p.vx = p.face * Math.max(9, Math.abs(p.vx));
  const oldBottom = p.y + p.h;
  p.vy += .54 * step; p.vy = Math.min(p.vy, 12); p.x += p.vx * step; p.y += p.vy * step;
  p.x = clamp(p.x, 0, world.length - p.w);
  p.grounded = false;
  for (const platform of world.platforms) {
    if (p.x + p.w > platform.x && p.x < platform.x + platform.w && oldBottom <= platform.y + 3 && p.y + p.h >= platform.y && p.vy >= 0) {
      p.y = platform.y - p.h; p.vy = 0; p.grounded = true; p.jumps = 0;
    }
  }
  for (const item of world.yarn) {
    if (item.got) continue;
    const dx = p.x + p.w / 2 - item.x, dy = p.y + p.h / 2 - item.y;
