(() => {
'use strict';
const $=id=>document.getElementById(id), canvas=$('game'),ctx=canvas.getContext('2d'),W=canvas.width,H=canvas.height,G=466,KEY='whisker-woods-save-v1';
const cats=[{id:'marmalade',name:'Marmalade',emoji:'🐈',color:'#d99a68',ability:'Nimble little jumper',cost:0,skill:'Extra-high jump'},{id:'pudding',name:'Pudding',emoji:'🐈',color:'#ecd7ba',ability:'A second chance in the air',cost:18,skill:'Double jump'},{id:'nimbus',name:'Nimbus',emoji:'🐈‍⬛',color:'#8999a8',ability:'A breezy burst of speed',cost:28,skill:'Cloud dash'},{id:'clover',name:'Clover',emoji:'🐈',color:'#99ae78',ability:'A lucky little shield',cost:38,skill:'Protective purr'}];
const fresh=()=>({yarn:0,lives:7,level:1,unlocked:['marmalade'],upgrades:{},selected:'marmalade'});
function load(){try{const d=JSON.parse(localStorage.getItem(KEY));if(!d)return fresh();return {yarn:Math.max(0,+d.yarn||0),lives:Math.max(1,Math.min(7,+d.lives||7)),level:Math.max(1,+d.level||1),unlocked:[...new Set(['marmalade',...(Array.isArray(d.unlocked)?d.unlocked.filter(id=>cats.some(c=>c.id===id)):[])])],upgrades:d.upgrades||{},selected:(d.unlocked||[]).includes(d.selected)?d.selected:'marmalade'};}catch{return fresh();}}
let save=load(),state='title',paused=false,soundOn=true,last=0,camera=0,world,player,toastTimer,particles=[],keys=Object.create(null),touch={left:false,right:false};
const clamp=(x,a,b)=>Math.max(a,Math.min(b,x)),cat=()=>cats.find(c=>c.id===save.selected)||cats[0],title=()=>['Mossy Meadow','Dewdrop Woods','Sunbeam Hollow','Clover Creek','Moonberry Trail'][(save.level-1)%5];
function rounded(x,y,w,h,r,color){ctx.fillStyle=color;ctx.beginPath();ctx.roundRect(x,y,w,h,Math.min(r,w/2,h/2));ctx.fill();}
function beep(freq=550,dur=.08){if(!soundOn)return;try{const a=new(window.AudioContext||window.webkitAudioContext)(),o=a.createOscillator(),g=a.createGain();o.frequency.value=freq;g.gain.setValueAtTime(.05,a.currentTime);g.gain.exponentialRampToValueAtTime(.001,a.currentTime+dur);o.connect(g);g.connect(a.destination);o.start();o.stop(a.currentTime+dur);o.onended=()=>a.close();}catch{}}
function notify(msg){const e=$('toast');e.textContent=msg;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2200);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(save));}catch{}refreshUI();}
function buildWorld(){const length=3650+Math.min(save.level-1,8)*150,platforms=[[0,570],[650,560],[1290,590],[1950,550],[2570,570],[3210,length-3210]].map(([x,w])=>({x,y:G,w,h:90})),ledges=[[250,380,125],[440,325,115],[730,365,140],[930,300,130],[1130,382,110],[1370,350,130],[1580,292,120],[1770,365,125],[2010,375,140],[2230,310,120],[2440,365,110],[2670,355,130],[2860,292,130],[3060,370,115],[3310,360,140],[3500,300,120]];
ledges.forEach(([x,y,w])=>platforms.push({x,y,w,h:18,ledge:true}));const yarn=[];[[110,415],[195,415],[280,344],[335,344],[465,289],[520,289],[735,415],[790,329],[850,329],[960,264],[1020,264],[1150,347],[1335,415],[1405,314],[1465,314],[1600,256],[1660,256],[1795,329],[1995,415],[2060,339],[2130,339],[2250,274],[2310,274],[2455,329],[2620,415],[2705,319],[2770,319],[2885,256],[2945,256],[3090,334],[3260,415],[3340,324],[3400,324],[3525,264],[3580,264]].forEach(([x,y])=>yarn.push({x,y,got:false,phase:Math.random()*6}));return {length,platforms,yarn,hazards:[570,1210,1880,2505,3145].map(x=>({x,y:G-10,w:28,h:10})),exitX:length-100,clouds:Array.from({length:10},(_,i)=>({x:i*440+Math.random()*180,y:55+Math.random()*135,s:.7+Math.random()*.55}))};}
function initLevel(){world=buildWorld();camera=0;particles=[];player={x:70,y:G-44,vx:0,vy:0,w:36,h:44,face:1,grounded:false,jumps:0,invuln:0,dash:0,shield:0,cool:0,flash:0};refreshUI();}
function refreshUI(){if(!world)return;$('levelName').textContent=`${title()} · ${String(save.level).padStart(2,'0')}`;$('yarnCount').textContent=save.yarn;$('lifeCount').textContent='♥ '.repeat(save.lives).trim()||'♡';$('catName').textContent=cat().name;$('catAbility').textContent=cat().ability;$('catAvatar').textContent=cat().emoji;const got=world.yarn.filter(y=>y.got).length;$('questProgress').style.width=`${got/world.yarn.length*100}%`;$('questText').textContent=`${got} / ${world.yarn.length}`;$('tipText').textContent=`${cat().skill} · press Shift or ✦ to use your skill.`;$('shopYarn').textContent=save.yarn;renderRoster();}
function renderRoster(){$('catRoster').innerHTML=cats.map(c=>{const owned=save.unlocked.includes(c.id),up=save.upgrades[c.id]||0;return `<button class="roster-cat${save.selected===c.id?' active':''}${owned?'':' locked'}" data-roster="${c.id}" aria-label="${c.name}">${c.emoji}${owned?(up?`<span class="level-badge">${up+1}</span>`:''):'<span class="lock">🔒</span>'}</button>`}).join('');}
function renderShop(){$('shopYarn').textContent=save.yarn;$('shopList').innerHTML=cats.map(c=>{const owned=save.unlocked.includes(c.id),up=save.upgrades[c.id]||0,price=16+up*14;let btn=!owned?`<button class="shop-buy" data-buy="${c.id}" ${save.yarn<c.cost?'disabled':''}>🧶 ${c.cost}</button>`:save.selected!==c.id?`<button class="shop-buy" data-select="${c.id}">Choose</button>`:up<3?`<button class="shop-buy" data-upgrade="${c.id}" ${save.yarn<price?'disabled':''}>Upgrade · 🧶 ${price}</button>`:'<button class="shop-buy" disabled>Max level</button>';return `<div class="shop-item"><div class="shop-emoji">${c.emoji}</div><div class="shop-item-info"><b>${c.name}</b><small>${c.skill}${owned&&up?` · upgrade ${up}/3`:''}</small></div>${btn}</div>`}).join('');}
function openShop(){renderShop();$('shopModal').classList.remove('hidden');if(state==='playing'){paused=true;$('pauseOverlay').classList.add('hidden');}}
function closeShop(){ $('shopModal').classList.add('hidden');if(state==='playing')paused=false;}
function startGame(){save.lives=7;persist();initLevel();state='playing';paused=false;['startScreen','gameOverModal','levelModal','pauseOverlay'].forEach(id=>$(id).classList.add('hidden'));notify(`Off to ${title()}!`);beep(620);}
function jump(){if(state!=='playing'||paused)return;const up=save.upgrades[cat().id]||0;if(player.grounded||(cat().id==='pudding'&&player.jumps<2)){player.vy=player.grounded?-(cat().id==='marmalade'?11.6:10.3)-up*.45:-9.1;player.grounded=false;player.jumps++;beep(470);}}
function ability(){if(state!=='playing'||paused||player.cool>0)return;const id=cat().id,up=save.upgrades[id]||0;if(id==='nimbus'){player.dash=12;player.vx=player.face*(13+up);player.vy*=.35;}else if(id==='clover')player.shield=360+up*90;else if(id==='pudding'){if(!player.grounded&&player.jumps<2)jump();else player.invuln=35;}else if(player.grounded)jump();else player.vy=Math.min(player.vy,-8.7-up*.5);player.cool=120;player.flash=16;beep(760,.12);}
function loseLife(){if(player.invuln>0||player.shield>0){if(player.shield>0)player.shield=0;player.invuln=65;return;}save.lives=Math.max(0,save.lives-1);persist();beep(180,.2);if(!save.lives){state='gameover';$('gameOverModal').classList.remove('hidden');return;}player.x=Math.max(50,Math.floor(player.x/650)*650+55);player.y=G-70;player.vx=player.vy=0;player.invuln=100;player.jumps=0;camera=clamp(player.x-W*.28,0,world.length-W);notify(`${save.lives} paw power left.`);}
function complete(){if(state!=='playing')return;state='level';paused=true;const reward=8+world.yarn.filter(y=>y.got).length;save.yarn+=reward;persist();$('levelReward').textContent=`+${reward}`;$('levelMessage').textContent=`You gathered ${world.yarn.filter(y=>y.got).length} yarn balls and found the cottage. What a lovely adventure!`;$('levelModal').classList.remove('hidden');beep(830,.2);}
// APPEND
})();

