  function complete(){if(state!=='playing')return;state='level';paused=true;const reward=8+world.yarn.filter(y=>y.got).length;save.yarn+=reward;persist();$('levelReward').textContent=`+${reward}`;$('levelMessage').textContent=`You gathered ${world.yarn.filter(y=>y.got).length} yarn balls and found the cottage. What a lovely adventure!`;$('levelModal').classList.remove('hidden');beep(830,.2);}

function rects(a,b){return a.x<b.x+b.w&&a.x+a.w>b.x&&a.y<b.y+b.h&&a.y+a.h>b.y}

function update(dt){
  if(state!=='playing'||paused)return;
  dt=clamp(dt,.5,2);
  const left=keys.ArrowLeft||keys.KeyA||touch.left,right=keys.ArrowRight||keys.KeyD||touch.right;
  player.face=left?-1:right?1:player.face;
  let target=(right?1:0)-(left?1:0),speed=cat().id==='nimbus'?5.4:4.5+(save.upgrades[cat().id]||0)*.12;
  if(player.dash>0){player.dash-=dt;speed*=1.2}else player.vx+=(target*speed-player.vx)*.22*dt;
  if(!target)player.vx*=Math.pow(.82,dt);
  player.vy+=.55*dt;player.vy=Math.min(player.vy,14);
  player.x+=player.vx*dt;
  player.x=clamp(player.x,0,world.length-45);

  player.grounded=false;
  player.y+=player.vy*dt;
  for(const p of world.platforms){
    if(rects({x:player.x,y:player.y,w:player.w,h:player.h},p)&&player.vy>=0&&player.y+player.h-player.vy*dt<=p.y+8){
      player.y=p.y-player.h;player.vy=0;player.grounded=true;player.jumps=0;
    }
  }
  if(player.y>H+80)loseLife();
  if(player.invuln>0)player.invuln-=dt;if(player.shield>0)player.shield-=dt;if(player.cool>0)player.cool-=dt;if(player.flash>0)player.flash-=dt;

  for(const y of world.yarn){if(!y.got){const dx=player.x+18-y.x,dy=player.y+22-y.y;if(dx*dx+dy*dy<24*24){y.got=true;save.yarn++;persist();spawnSpark(y.x,y.y);beep(690,.07);}}}
  for(const h of world.hazards){if(rects({x:player.x,y:player.y,w:player.w,h:player.h},h)){loseLife();break}}
  if(player.x+player.w>world.exitX&&player.y+player.h>G-20)complete();

  camera+=(clamp(player.x-W*.38,0,world.length-W)-camera)*.12*dt;
  for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=.08*dt;p.life-=dt;if(p.life<=0)particles.splice(i,1)}
  refreshUI();
}

function spawnSpark(x,y){for(let i=0;i<9;i++)particles.push({x,y,vx:(Math.random()-0.5)*4,vy:(Math.random()-1)*3,life:20+Math.random()*20,color:i%2?'#dfb45a':'#fff7d7'})}

function drawCloud(c,parallax){const x=c.x-camera*.18*c.s+parallax;rounded(x,c.y,110*c.s,27*c.s,18*c.s,'#fffdf0cc');rounded(x+22*c.s,c.y-15*c.s,48*c.s,30*c.s,15*c.s,'#fffdf0cc')}
function draw(){
  ctx.clearRect(0,0,W,H);
  const sky=ctx.createLinearGradient(0,0,0,H);sky.addColorStop(0,'#bddccd');sky.addColorStop(.72,'#dfe8bf');sky.addColorStop(1,'#b9ad7c');ctx.fillStyle=sky;ctx.fillRect(0,0,W,H);
  world.clouds.forEach(c=>drawCloud(c,0));
  ctx.fillStyle='#92b09a';ctx.beginPath();ctx.moveTo(0,430);for(let x=0;x<=W;x+=120){ctx.quadraticCurveTo(x+60,330-(x/5%70),x+120,430)}ctx.lineTo(W,H);ctx.lineTo(0,H);ctx.fill();
  ctx.fillStyle='#789b7e';for(let i=-1;i<12;i++){const x=i*120-camera*.35%120;ctx.beginPath();ctx.moveTo(x,430);ctx.lineTo(x+38,330);ctx.lineTo(x+82,430);ctx.fill();}
  ctx.save();ctx.translate(-camera,0);
  ctx.fillStyle='#718f66';ctx.fillRect(0,466,world.length,H-466);
  ctx.fillStyle='#b1a866';ctx.fillRect(0,466,world.length,10);
  for(const p of world.platforms){rounded(p.x,p.y,p.w,p.h,p.ledge?9:0,p.ledge?'#a9a66f':'#718760');if(p.ledge){ctx.fillStyle='#72905d';ctx.fillRect(p.x,p.y,p.w,5)}}
  for(let i=0;i<world.length;i+=75){ctx.fillStyle='#5e8058';ctx.fillRect(i,476,3,35)}
  ctx.fillStyle='#657c55';world.hazards.forEach(h=>{ctx.beginPath();ctx.moveTo(h.x,h.y+h.h);for(let x=h.x;x<h.x+h.w;x+=7){ctx.lineTo(x,h.y+((x-h.x)%14?8:0));ctx.lineTo(x+7,h.y+h.h)}ctx.fill()});
  for(const y of world.yarn){if(y.got)continue;const bob=Math.sin(performance.now()/260+y.phase)*4;ctx.save();ctx.translate(y.x,y.y+bob);ctx.fillStyle='#e6aa70';ctx.beginPath();ctx.arc(0,0,10,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#fff1d2';ctx.lineWidth=2;ctx.beginPath();ctx.arc(-2,-1,5,0,Math.PI*1.7);ctx.stroke();ctx.restore()}
  drawCottage();
  if(player.flash>0){ctx.globalAlpha=.35;ctx.fillStyle='#fff8cb';ctx.beginPath();ctx.arc(player.x+18,player.y+22,30,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
  if(player.shield>0){ctx.strokeStyle='#eaf8df';ctx.lineWidth=4;ctx.globalAlpha=.75;ctx.beginPath();ctx.arc(player.x+18,player.y+22,31,0,Math.PI*2);ctx.stroke();ctx.globalAlpha=1}
  drawCat(player.x,player.y,player.face,player.invuln>0&&Math.floor(player.invuln/5)%2===0);
  for(const p of particles){ctx.globalAlpha=clamp(p.life/25,0,1);ctx.fillStyle=p.color;ctx.beginPath();ctx.arc(p.x,p.y,3,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;
  ctx.restore();
}
function drawCottage(){const x=world.exitX-25,y=G-104;ctx.fillStyle='#7f6e58';ctx.fillRect(x,y+45,110,59);ctx.fillStyle='#d8bc82';ctx.fillRect(x-8,y+38,126,66);ctx.fillStyle='#6f5a48';ctx.beginPath();ctx.moveTo(x-18,y+43);ctx.lineTo(x+55,y-5);ctx.lineTo(x+128,y+43);ctx.closePath();ctx.fill();ctx.fillStyle='#4f6d57';ctx.fillRect(x+43,y+64,28,40);ctx.fillStyle='#d8d09a';ctx.beginPath();ctx.arc(x+72,y+83,3,0,Math.PI*2);ctx.fill();ctx.fillStyle='#7f9c79';ctx.fillRect(x+12,y+58,22,20)}
function drawCat(x,y,face,hidden){if(hidden)return;ctx.save();ctx.translate(x+18,y+22);ctx.scale(face,1);ctx.fillStyle=cat().color;ctx.beginPath();ctx.ellipse(0,10,17,20,0,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(-12,-8);ctx.lineTo(-9,-23);ctx.lineTo(1,-12);ctx.moveTo(10,-11);ctx.lineTo(14,-24);ctx.lineTo(17,-7);ctx.fill();ctx.fillStyle='#fff0d5';ctx.beginPath();ctx.ellipse(-3,11,8,13,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#34453e';ctx.beginPath();ctx.arc(-7,-4,1.8,0,Math.PI*2);ctx.arc(7,-4,1.8,0,Math.PI*2);ctx.fill();ctx.fillStyle='#b87972';ctx.beginPath();ctx.moveTo(0,1);ctx.lineTo(-3,5);ctx.lineTo(3,5);ctx.fill();ctx.strokeStyle=cat().color;ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(13,12);ctx.quadraticCurveTo(28,8,23,-7);ctx.stroke();ctx.restore()}

function loop(t){const dt=last?clamp((t-last)/16.67,.5,2):1;last=t;update(dt);draw();requestAnimationFrame(loop)}

window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','ArrowUp','Space','ShiftLeft','ShiftRight','KeyA','KeyD','KeyW'].includes(e.code))e.preventDefault();keys[e.code]=true;if(e.code==='Space'||e.code==='ArrowUp'||e.code==='KeyW')jump();if(e.code==='ShiftLeft'||e.code==='ShiftRight')ability();if(e.code==='Escape'&&state==='playing')togglePause()},{passive:false});
window.addEventListener('keyup',e=>{keys[e.code]=false});
function togglePause(){paused=!paused;$('pauseOverlay').classList.toggle('hidden',!paused)}

$('startButton').addEventListener('click',startGame);$('pauseButton').addEventListener('click',togglePause);$('resumeButton').addEventListener('click',togglePause);$('shopButton').addEventListener('click',openShop);$('catSwitch').addEventListener('click',openShop);
$('nextLevelButton').addEventListener('click',()=>{save.level++;persist();startGame();});$('levelShopButton').addEventListener('click',()=>openShop());$('retryButton').addEventListener('click',()=>{save.lives=7;startGame()});
