$('catRoster').addEventListener('click',e=>{const b=e.target.closest('[data-roster]');if(!b)return;const id=b.dataset.roster;if(save.unlocked.includes(id)){save.selected=id;persist();notify(`${cat().name} is ready!`)}else openShop()});
document.querySelectorAll('[data-control]').forEach(b=>{const control=b.dataset.control;const down=e=>{e.preventDefault();if(control==='left')touch.left=true;if(control==='right')touch.right=true;if(control==='jump')jump();if(control==='ability')ability()};const up=e=>{e.preventDefault();if(control==='left')touch.left=false;if(control==='right')touch.right=false};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('pointerleave',up)});
